import{_ as t,o as a,c as r,ag as e}from"./chunks/framework.D5hoimZQ.js";const c=JSON.parse('{"title":"方法论：从表层到第一性原理","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/appendix/methodology.md","filePath":"science-log/src/appendix/methodology.md"}'),l={name:"science-log/src/appendix/methodology.md"};function i(n,o,s,h,d,u){return a(),r("div",null,[...o[0]||(o[0]=[e('<h1 id="方法论-从表层到第一性原理" tabindex="-1">方法论：从表层到第一性原理 <a class="header-anchor" href="#方法论-从表层到第一性原理" aria-label="Permalink to &quot;方法论：从表层到第一性原理&quot;">​</a></h1><h2 id="三层下钻法" tabindex="-1">三层下钻法 <a class="header-anchor" href="#三层下钻法" aria-label="Permalink to &quot;三层下钻法&quot;">​</a></h2><p>科学日志的核心方法论是<strong>三层下钻</strong>——从新闻标题逐层拆解到最底层的物理/数学原理。</p><h3 id="第一层-表层扩展" tabindex="-1">第一层：表层扩展 <a class="header-anchor" href="#第一层-表层扩展" aria-label="Permalink to &quot;第一层：表层扩展&quot;">​</a></h3><p><strong>目标</strong>：回答&quot;是什么&quot;和&quot;为什么重要&quot;。</p><ul><li>补充研究背景（谁做的、在哪发表、用了什么方法）</li><li>关联相关领域趋势</li><li>提供历史脉络和未来展望</li></ul><p><strong>示例</strong>：腹泻细菌&quot;阿喀琉斯之踵&quot; → ETEC 和志贺氏菌共用三种黏液酶，靶向保守区域可广谱预防。</p><h3 id="第二层-机制层" tabindex="-1">第二层：机制层 <a class="header-anchor" href="#第二层-机制层" aria-label="Permalink to &quot;第二层：机制层&quot;">​</a></h3><p><strong>目标</strong>：回答&quot;怎么工作的&quot;。</p><ul><li>拆解分子机制、信号通路、物理过程</li><li>引入关键概念和术语定义</li><li>建立因果链条</li></ul><p><strong>示例</strong>：MUC2 的 vWD 二聚化 → PTS 糖基化 → CysD 六边形网状 → CK 稳定。EatA 通过 V 型分泌系统转运到表面，切割 MUC2 肽骨架。</p><h3 id="第三层-第一性原理层" tabindex="-1">第三层：第一性原理层 <a class="header-anchor" href="#第三层-第一性原理层" aria-label="Permalink to &quot;第三层：第一性原理层&quot;">​</a></h3><p><strong>目标</strong>：回答&quot;为什么必须是这样&quot;。</p><ul><li>从物理定律、数学原理、演化逻辑出发</li><li>揭示深层统一规律</li><li>建立跨领域关联</li></ul><p><strong>示例</strong>：黏液层是物理屏障，EatA 是&quot;破壁酶&quot;。中断破壁酶 = 保留屏障。这与 ASF 的 Friction Hypothesis 同构——约束维护结构，消除约束 = 崩溃。</p><h2 id="分析原则" tabindex="-1">分析原则 <a class="header-anchor" href="#分析原则" aria-label="Permalink to &quot;分析原则&quot;">​</a></h2><ol><li><strong>不编造</strong>：每一条机制描述必须有文献支撑</li><li><strong>可追溯</strong>：从效应到分子的因果链条必须完整</li><li><strong>可证伪</strong>：分析的结论应能推导出可验证的预测</li><li><strong>跨领域关联</strong>：主动寻找不同领域间的深层同构</li></ol><h2 id="工具链" tabindex="-1">工具链 <a class="header-anchor" href="#工具链" aria-label="Permalink to &quot;工具链&quot;">​</a></h2><ul><li><strong>信息获取</strong>：web_search（多查询并行）+ 飞书知识库</li><li><strong>内容组织</strong>：Markdown 结构化写作</li><li><strong>版本管理</strong>：GitHub 同步 + 目录索引</li><li><strong>发布</strong>：mdBook 构建 → GitHub Pages 部署</li></ul>',19)])])}const p=t(l,[["render",i]]);export{c as __pageData,p as default};
